#{poolId}
UNION
SELECT bond.issuer_code AS security_code ,bond.issuer AS security_short_name ,'company' AS security_type FROM ip_pool_status ips INNER JOIN rrs_securityinfo bond ON bond.wind_code = ips.security_code INNER JOIN dict_security_type dst ON dst.security_type = bond.security_type AND dst.category_type = 'bond' AND dst.is_deleted = 0 WHERE ips.audit_status = '20' AND ips.is_deleted = 0 AND bond.security_status != 'D' AND (bond.maturity_date IS NULL OR bond.maturity_date >= DATE_FORMAT(CURDATE(), '%Y%m%d')) AND ips.target_pool_id IN
#{poolId}
